head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.POPUP_URL_DETAIL = "/ui/lst/pf/ULDSTF09303.xml";      // 상장형 수익증권 신규상장관리 팝업 (원본 리터럴)
scwin.POPUP_URL_ISU = "/ui/lst/common/ULDSTF05012.xml";      // 종목 선택(공통)
scwin.USER_MKT_FIXED = ["1", "2", "6"];                       // 자기 시장으로 고정하고 시장구분을 숨기는 사용자 시장 (원본 js_market 분기)

// 원본 : /pf/ULDSTF09302.gfm (상장형 수익증권 신규상장) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF09302/ULDSTF09302.xml)
/*
 * 화면 동작
 *  - 증권구분·상장일기간·종목·시장구분으로 신규상장 목록을 조회한다(진입 시 자동 조회).
 *  - 행 더블클릭 → 그 건으로, [신규] → 고른 유가증권으로 신규상장관리 팝업(ULDSTF09303)을 연다.
 *    저장하고 닫혔거나 X 로 닫혔으면 다시 조회해 보던 행으로 돌아간다(pf 공통 계약서 재조회 규약).
 *  - 통신은 화면에 적용된 API(경로·method·keyInfo)를 명세로 간주한다(사용자 결정 2026-10-29 준용).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09302/ULDSTF09302.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 기간선택 콤보·기본 기간 → 달력·Enter 키 바인딩 → 사용자 시장별 화면 → 목록 조회. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 기간선택 콤보와 기본 기간(시작 19000101 ~ 종료 오늘+60일) — 원본 comboCbDataSetPeriod + initSearchDate
    $c.data.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.lc.initSearchDate(edt_SDate, edt_EDate);

    // 2) 기간 달력 선후 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.compareFromToDate(edt_SDate, edt_EDate, ["상장일기간 시작일", "상장일기간 종료일"]);
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 유가·코스닥·(6) 사용자는 자기 시장으로 고정하고 시장구분 열·조건을 숨긴다 (원본 그대로 — §8 #5)
    const userMarket = String($c.session.getUserInfo("market") ?? "");
    if (scwin.USER_MKT_FIXED.includes(userMarket)) {
        grd_List.setColumnVisible("trMktNm", false);
        rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue(userMarket);
        panel_mkt_gubun.hide();
    } else {
        panel_mkt_gubun.show("");
    }

    // 4) 목록 조회
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 클릭 — 상장일기간 시작일이 종료일보다 늦지 않으면 목록을 조회한다. (원본 btn_Search_onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!$c.date.dateCompare(edt_SDate.getValue(), edt_EDate.getValue())) {
            // 원본은 안내 없이 조회만 하지 않았다 — 이유를 알 수 있게 안내한다 (§8 #6)
            await $c.win.alert("상장일기간 시작일이 종료일보다 늦습니다.");
            edt_SDate.focus();
            return;
        }
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_IsuSearch_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기 클릭 — 종목 선택(ULDSTF05012)을 열어 종목코드·종목명을 채운다. (원본 img_IsuSearch_onclick — §4, §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_IsuSearch_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.img_IsuSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.txb_ISU_CD_onblur
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목코드 칸을 벗어날 때 종목코드가 비었으면 종목명도 비운다.
 * 개발 사본은 이 연결이 userData2(Gauce 잔재)에만 있어 동작하지 않았다 — ev:onblur 로 연결한다. (원본 txb_ISU_CD_onblur — §4, §8 #3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function (e) {
    try {
        if ($c.util.isEmpty(txb_ISU_CD.getValue())) {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09302.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name scwin.cmb_PeriodTp_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기간선택 — 고른 기간으로 시작일·종료일을 채운다. 콤보 값(0~6)은 index 와 같고 공통 함수는 숫자로 비교하므로 index 를 넘긴다.
 * (원본 cmb_PeriodTp_OnSelChange — §4)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_PeriodTp_onviewchange = function (info) {
    try {
        $c.stf.setFromToDate(cmb_PeriodTp.getSelectedIndex(), edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09302.cmb_PeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 행 더블클릭 — 그 건으로 신규상장관리 팝업을 연다. (원본 grd_List_OnDblClick → openDetail(row) — §4)
 * @param {Number} rowIndex 행 번호
 * @param {Number} columnIndex 열 번호
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 클릭. (원본 btn_Excel_onclick → excelDown — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 클릭 — 신규등록할 유가증권을 골랐으면 신규상장관리 팝업을 신규로 연다. (원본 btn_New_onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09302.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규상장 목록 조회 — 조회조건(dma_selectListReq)으로 목록을 받고 건수를 표시한다. (원본 list_sync + dts_List_OnLoadCompleted — §5.1)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/pf/new-listing/select-list",
        ref : "dma_selectListReq",
        target : "dlt_selectListRes=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)

    panel_page.setValue(dlt_selectListRes.getRowCount());
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 신규등록할 유가증권이 없으면 안내하고, 있으면 신규상장관리 팝업을 신규로 연다. (원본 btn_New_onclick 본문 — §6.1)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    if ($c.util.isEmpty(cmb_NEW_SECUGRP_ID.getValue())) {
        await $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
        cmb_NEW_SECUGRP_ID.focus();
        return;
    }
    await scwin.openDetail(-1);
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규상장관리 팝업(ULDSTF09303)을 연다. 행이면 그 건의 업무처리번호·증권그룹, 신규면 빈 번호와 신규 유가증권을 넘긴다.
 * 저장하고 닫혔거나 X 로 닫혔으면 다시 조회해 보던 행으로 돌아간다. 원본은 팝업이 이 화면의 clickBzProcsNo·그리드·콤보를 직접 읽고
 * 저장 뒤 이 화면 그리드를 직접 움직였다. (원본 openDetail — §6.2, 가이드 §6.5)
 * @param {Number} rowIndex 행 번호 (신규면 -1)
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    let bzProcsNo = "";
    let secugrpId = "";

    if (rowIndex >= 0) {
        bzProcsNo = String(dlt_selectListRes.getCellData(rowIndex, "bzProcsNo") ?? "");
        secugrpId = String(dlt_selectListRes.getCellData(rowIndex, "secugrpId") ?? "");
    } else {
        secugrpId = cmb_NEW_SECUGRP_ID.getValue();
    }

    const data = {
        bzProcsNo : bzProcsNo,      // 원본 parentWin.scwin.clickBzProcsNo (신규 "")
        secugrpId : secugrpId       // 원본 parentWin.cmb_NEW_SECUGRP_ID (신규) — 행이면 그 행의 증권그룹
    };
    const options = {
        id : "ULDSTF09303",
        popupName : "상장형 수익증권 신규상장관리",
        width : 1320,
        height : 900,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const res = await $c.win.openPopup(scwin.POPUP_URL_DETAIL, options, data);

    // 저장하고 닫힘 또는 창 닫기(X — 저장 여부를 모르므로 다시 조회) — pf 공통 계약서 재조회 규약
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.selectList()) return;
    scwin.restoreRow(bzProcsNo, rowIndex);
};

/**
 * @method
 * @name scwin.restoreRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 다시 조회한 뒤 보던 행으로 돌아간다 — 같은 업무처리번호 행, 없으면 원래 행 번호. 신규로 연 경우는 그대로 둔다.
 * (원본 팝업의 parentWin.grd_List.setFocusedCell(rowPos) — §6.2)
 * @param {String} bzProcsNo 연 건의 업무처리번호
 * @param {Number} rowIndex 연 행 번호 (신규면 -1)
 * @returns
 * @hidden N
 */
scwin.restoreRow = function (bzProcsNo, rowIndex) {
    const rowCount = dlt_selectListRes.getRowCount();
    if (rowIndex < 0 || rowCount === 0) return;

    let focusRow = -1;
    for (let i = 0; i < rowCount; i++) {
        if (String(dlt_selectListRes.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo) {
            focusRow = i;
            break;
        }
    }
    if (focusRow < 0 && rowIndex < rowCount) focusRow = rowIndex;
    if (focusRow >= 0) grd_List.setFocusedCell(focusRow, 0);
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 선택(ULDSTF05012)을 증권구분·조회유형 SLR·시장구분으로 열고, 고른 종목의 코드·이름을 채운다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_IsuSearch_onclick — §6.3)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const data = {
        secugrpId : rdo_SECUGRP_ID.getValue(),
        searchTyp : "SLR",
        mktTpCd : rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue()
    };
    const options = {
        id : "ULDSTF05012",
        popupName : "종목 선택",
        width : 600,
        height : 640,
        frameModal : "top",
        type : "pageFramePopup"
    };
    const res = await $c.win.openPopup(scwin.POPUP_URL_ISU, options, data);
    if ($c.util.isEmpty(res?.isuCd)) return;    // 취소·X 도 { isCloseButtonClick } 객체라 종목코드로 판정

    txb_ISU_CD.setValue(String(res.isuCd));
    txb_ISU_NM.setValue(String(res.isuNm ?? ""));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 조회 결과가 없으면 안내한다. (원본 excelDown — §6.4)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    if (dlt_selectListRes.getRowCount() === 0) {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_신규상장_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
